<?php
require_once dirname(__DIR__).'/includes/auth.php';
$u=require_role('dean');
$facultyId=(int)($u['faculty_id']??0);
if(!$facultyId){http_response_code(403);exit('Your Dean account has no assigned faculty. Contact the administrator.');}
$q=db()->prepare('SELECT name FROM faculties WHERE id=? AND is_active=1');$q->execute([$facultyId]);$faculty=$q->fetchColumn();
if(!$faculty){http_response_code(403);exit('Your faculty assignment is unavailable.');}

$q=db()->prepare('SELECT COUNT(*) FROM departments WHERE faculty_id=? AND is_active=1');$q->execute([$facultyId]);$deptCount=(int)$q->fetchColumn();
$q=db()->prepare("SELECT COUNT(*) FROM users u JOIN departments d ON d.id=u.department_id JOIN roles r ON r.id=u.role_id WHERE d.faculty_id=? AND d.is_active=1 AND r.name='student'");$q->execute([$facultyId]);$students=(int)$q->fetchColumn();
$q=db()->prepare("SELECT COUNT(*) FROM users u JOIN departments d ON d.id=u.department_id JOIN roles r ON r.id=u.role_id WHERE d.faculty_id=? AND d.is_active=1 AND r.name='supervisor' AND u.account_status='active'");$q->execute([$facultyId]);$supervisors=(int)$q->fetchColumn();
$q=db()->prepare('SELECT COUNT(*) FROM projects p JOIN departments d ON d.id=p.department_id WHERE d.faculty_id=?');$q->execute([$facultyId]);$projects=(int)$q->fetchColumn();
$q=db()->prepare("SELECT COUNT(*) FROM projects p JOIN departments d ON d.id=p.department_id WHERE d.faculty_id=? AND p.status NOT IN ('completed','archived')");$q->execute([$facultyId]);$activeProjects=(int)$q->fetchColumn();
$q=db()->prepare("SELECT COUNT(*) FROM projects p JOIN departments d ON d.id=p.department_id WHERE d.faculty_id=? AND p.status IN ('completed','archived')");$q->execute([$facultyId]);$completedProjects=(int)$q->fetchColumn();
$q=db()->prepare("SELECT COUNT(*) FROM projects p JOIN departments d ON d.id=p.department_id WHERE d.faculty_id=? AND p.status IN ('idea_submitted','idea_under_review','supervisor_pending','correction_required','under_evaluation')");$q->execute([$facultyId]);$attentionProjects=(int)$q->fetchColumn();
$q=db()->prepare("SELECT d.name department,(SELECT COUNT(*) FROM users u JOIN roles r ON r.id=u.role_id WHERE u.department_id=d.id AND r.name='student') students,(SELECT COUNT(*) FROM users u JOIN roles r ON r.id=u.role_id WHERE u.department_id=d.id AND r.name='supervisor' AND u.account_status='active') supervisors,(SELECT COUNT(*) FROM projects p WHERE p.department_id=d.id) projects,(SELECT COUNT(*) FROM projects p WHERE p.department_id=d.id AND p.status NOT IN ('completed','archived')) active_projects,(SELECT COUNT(*) FROM projects p WHERE p.department_id=d.id AND p.status IN ('completed','archived')) completed_projects,(SELECT COUNT(*) FROM projects p WHERE p.department_id=d.id AND p.status IN ('idea_submitted','idea_under_review','supervisor_pending','correction_required','under_evaluation')) attention,(SELECT GROUP_CONCAT(CONCAT(h.first_name,' ',h.last_name) SEPARATOR ', ') FROM users h JOIN roles hr ON hr.id=h.role_id WHERE h.department_id=d.id AND hr.name='coordinator' AND h.account_status='active') hod_names FROM departments d WHERE d.faculty_id=? AND d.is_active=1 ORDER BY d.name");$q->execute([$facultyId]);$departments=$q->fetchAll();
$q=db()->prepare('SELECT p.reference_no,p.title,p.status,d.name department,s.name session_name FROM projects p JOIN departments d ON d.id=p.department_id JOIN academic_sessions s ON s.id=p.academic_session_id WHERE d.faculty_id=? ORDER BY p.updated_at DESC LIMIT 12');$q->execute([$facultyId]);$recent=$q->fetchAll();
$q=db()->prepare("SELECT u.id,u.first_name,u.last_name,u.staff_number,d.name department,COUNT(DISTINCT p.id) projects,COUNT(DISTINCT CASE WHEN s.status IN ('submitted','resubmitted','under_review') THEN s.id END) pending_reviews,COUNT(DISTINCT CASE WHEN p.status IN ('completed','archived') THEN p.id END) completed FROM users u JOIN roles r ON r.id=u.role_id JOIN departments d ON d.id=u.department_id LEFT JOIN project_supervisors ps ON ps.supervisor_id=u.id AND ps.ended_at IS NULL LEFT JOIN projects p ON p.id=ps.project_id LEFT JOIN submissions s ON s.project_id=p.id WHERE d.faculty_id=? AND d.is_active=1 AND r.name='supervisor' GROUP BY u.id ORDER BY d.name,u.last_name");$q->execute([$facultyId]);$staff=$q->fetchAll();
$q=db()->prepare("SELECT u.matric_number,u.first_name,u.last_name,u.profile_complete,d.name department,p.name programme,CONCAT_WS(' ',su.first_name,su.last_name) supervisor,pr.title project_title FROM users u JOIN roles r ON r.id=u.role_id JOIN departments d ON d.id=u.department_id LEFT JOIN programmes p ON p.id=u.programme_id LEFT JOIN student_supervisors ss ON ss.student_id=u.id AND ss.ended_at IS NULL LEFT JOIN users su ON su.id=ss.supervisor_id LEFT JOIN project_members pm ON pm.student_id=u.id LEFT JOIN projects pr ON pr.id=pm.project_id WHERE d.faculty_id=? AND d.is_active=1 AND r.name='student' ORDER BY d.name,u.last_name,u.first_name");$q->execute([$facultyId]);$facultyStudents=$q->fetchAll();
$q=db()->prepare("SELECT st.first_name,st.last_name,st.matric_number,d.name department,p.title project_title,s.document_type,s.status,s.submitted_at FROM submissions s JOIN projects p ON p.id=s.project_id JOIN departments d ON d.id=p.department_id JOIN users st ON st.id=s.student_id WHERE d.faculty_id=? ORDER BY s.submitted_at DESC LIMIT 10");$q->execute([$facultyId]);$recentActivity=$q->fetchAll();
$q=db()->prepare("SELECT COUNT(*) FROM submissions s JOIN projects p ON p.id=s.project_id JOIN departments d ON d.id=p.department_id WHERE d.faculty_id=? AND s.status IN ('submitted','resubmitted','under_review')");$q->execute([$facultyId]);$awaiting=(int)$q->fetchColumn();
$sessionName=(string)db()->query('SELECT name FROM academic_sessions WHERE is_current=1 LIMIT 1')->fetchColumn();
$supervisorReviewBacklog=count(array_filter($staff,fn($person)=>(int)$person['pending_reviews']>0));
$completionPct=$projects?(int)round($completedProjects/$projects*100):0;
$tones=['is-green','is-gold','is-blue','is-red'];
$pageTitle='Faculty Project Overview';$crumbTrail=['Dashboard'];require dirname(__DIR__).'/includes/header.php';
?>
<section class="dashboard-welcome"><div><h2>Faculty Final Year Project Overview</h2><p>Informational summary of student projects across the <?= e($faculty) ?>. This view is read-only; changes are handled by the Admin or each department HOD.</p></div><?php if($sessionName): ?><span class="welcome-session">Session <?= e($sessionName) ?></span><?php endif; ?></section>
<div class="row g-3 mb-3">
  <div class="col-sm-6 col-xl-3"><div class="stat-card"><div class="stat-label">Final year students</div><div class="stat-value"><?= (int)$students ?></div><small class="stat-sub"><?= (int)$deptCount ?> department<?= $deptCount===1?'':'s' ?></small></div></div>
  <div class="col-sm-6 col-xl-3"><div class="stat-card"><div class="stat-label">Active projects</div><div class="stat-value text-blue"><?= (int)$activeProjects ?></div><small class="stat-sub"><?= (int)$projects ?> registered in total</small></div></div>
  <div class="col-sm-6 col-xl-3"><div class="stat-card"><div class="stat-label">Completed projects</div><div class="stat-value text-green"><?= (int)$completedProjects ?></div><small class="stat-sub"><?= $completionPct ?>% faculty completion</small></div></div>
  <div class="col-sm-6 col-xl-3"><div class="stat-card"><div class="stat-label">Pending issues</div><div class="stat-value text-red"><?= (int)$attentionProjects ?></div><small class="stat-sub">HOD monitoring attention</small></div></div>
</div>
<section class="card p-4 mb-3"><h2 class="section-heading">Department &amp; Faculty Project Progress</h2><div class="row-table">
<?php foreach($departments as $i=>$d): $pct=(int)$d['projects']?(int)round(100*(int)$d['completed_projects']/(int)$d['projects']):0; ?><div class="meeting-row dept-row"><div class="dept-main"><strong><?= e($d['department']) ?> · <?= (int)$d['projects'] ?> project<?= (int)$d['projects']===1?'':'s' ?> · <?= $pct ?>%</strong><div class="progress <?= e($tones[$i%4]) ?>" role="progressbar" aria-label="<?= e($d['department']) ?> completion" aria-valuenow="<?= $pct ?>" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width:<?= $pct ?>%"></div></div></div><span class="ui-pill is-<?= ['ok','warn','info','bad'][$i%4] ?>"><?= (int)$d['completed_projects'] ?> completed</span></div><?php endforeach; ?>
<?php if(!$departments): ?><div class="empty-state m-3">No departments are configured for this faculty.</div><?php endif; ?></div></section>
<section class="card p-4 mb-3"><h2 class="section-heading">Pending Issues</h2><div class="row-table">
<div class="meeting-row"><strong>Projects needing attention</strong><span class="count-chip is-red"><?= (int)$attentionProjects ?></span></div>
<div class="meeting-row"><strong>Submissions awaiting review</strong><span class="count-chip is-gold"><?= (int)$awaiting ?></span></div>
<div class="meeting-row"><strong>Supervisors with pending reviews</strong><span class="count-chip is-blue"><?= (int)$supervisorReviewBacklog ?></span></div></div></section>
<section class="card p-4 mb-3"><h2 class="section-heading">Recent Faculty Activity</h2><div class="row-table">
<?php foreach($recent as $p): ?><div class="meeting-row"><div><strong><?= e($p['title']) ?></strong><p><?= e($p['reference_no'].' · '.$p['department'].' · '.$p['session_name']) ?></p></div><?= status_badge($p['status']) ?></div><?php endforeach; ?>
<?php if(!$recent): ?><div class="empty-state m-3">No projects registered in this faculty yet.</div><?php endif; ?></div></section>
<details class="card record-card mb-3"><summary><span class="section-heading mb-0">Department summary &amp; HODs</span><span class="chev"><?= ui_icon('chevron',16) ?></span></summary><div class="p-4 pt-2"><div class="table-responsive"><table class="table table-soft"><thead><tr><th>Department</th><th>HOD</th><th>Students</th><th>Supervisors</th><th>Projects</th><th>Active</th><th>Completed</th><th>Attention</th></tr></thead><tbody>
<?php foreach($departments as $d): ?><tr><td class="fw-bold"><?= e($d['department']) ?></td><td><?= e($d['hod_names']?:'Not assigned') ?></td><td><?= (int)$d['students'] ?></td><td><?= (int)$d['supervisors'] ?></td><td><?= (int)$d['projects'] ?></td><td><?= (int)$d['active_projects'] ?></td><td><?= (int)$d['completed_projects'] ?></td><td><?= (int)$d['attention'] ?></td></tr><?php endforeach; ?><?php if(!$departments): ?><tr><td colspan="8"><div class="empty-state">No department records are available.</div></td></tr><?php endif; ?></tbody></table></div></div></details>
<details class="card record-card mb-3"><summary><span class="section-heading mb-0">Supervisors in this faculty</span><span class="chev"><?= ui_icon('chevron',16) ?></span></summary><div class="p-4 pt-2"><div class="table-responsive"><table class="table table-soft"><thead><tr><th>Name</th><th>Staff no.</th><th>Department</th><th>Projects</th><th>Pending reviews</th><th>Completed</th></tr></thead><tbody>
<?php foreach($staff as $person): ?><tr><td class="fw-bold"><?= e(trim(($person['first_name']??'').' '.($person['last_name']??''))) ?></td><td><?= e($person['staff_number']??'—') ?></td><td><?= e($person['department']) ?></td><td><?= (int)$person['projects'] ?></td><td><?= (int)$person['pending_reviews'] ?></td><td><?= (int)$person['completed'] ?></td></tr><?php endforeach; ?>
<?php if(!$staff): ?><tr><td colspan="6"><div class="empty-state">No supervisors listed.</div></td></tr><?php endif; ?></tbody></table></div></div></details>
<details class="card record-card mb-3"><summary><span class="section-heading mb-0">Students and HOD supervisor assignments</span><span class="chev"><?= ui_icon('chevron',16) ?></span></summary><div class="p-4 pt-2"><div class="table-responsive"><table class="table table-soft"><thead><tr><th>Matric / student</th><th>Department</th><th>Programme</th><th>Supervisor</th><th>Project</th><th>Profile</th></tr></thead><tbody>
<?php foreach($facultyStudents as $s): ?><tr><td><strong><?= e($s['matric_number']??'—') ?></strong><br><small class="text-muted"><?= e(trim(($s['first_name']??'').' '.($s['last_name']??''))?:'Profile awaiting completion') ?></small></td><td><?= e($s['department']) ?></td><td><?= e($s['programme']??'—') ?></td><td><?= e($s['supervisor']?:'Not assigned') ?></td><td><?= e($s['project_title']?:'Not registered') ?></td><td><?= !empty($s['profile_complete'])?ui_pill('completed'):ui_pill('pending') ?></td></tr><?php endforeach; ?>
<?php if(!$facultyStudents): ?><tr><td colspan="6"><div class="empty-state">No students registered in this faculty.</div></td></tr><?php endif; ?></tbody></table></div></div></details>
<details class="card record-card"><summary><span class="section-heading mb-0">Recent submission activity</span><span class="chev"><?= ui_icon('chevron',16) ?></span></summary><div class="p-4 pt-2"><div class="table-responsive"><table class="table table-soft"><thead><tr><th>Student</th><th>Project and stage</th><th>Status</th><th>Date</th></tr></thead><tbody>
<?php foreach($recentActivity as $activity): ?><tr><td><?= e(trim(($activity['first_name']??'').' '.($activity['last_name']??''))) ?><br><small class="text-muted"><?= e($activity['matric_number']??'') ?> · <?= e($activity['department']) ?></small></td><td><?= e($activity['project_title']) ?><br><small><?= e(ui_doc_label($activity['document_type'])) ?></small></td><td><?= status_badge($activity['status']) ?></td><td><?= e(ui_date($activity['submitted_at'])) ?></td></tr><?php endforeach; ?><?php if(!$recentActivity): ?><tr><td colspan="4"><div class="empty-state">No submissions have been recorded yet.</div></td></tr><?php endif; ?></tbody></table></div></div></details>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
